                var aumLoss = 8.2 * (1 - marketingRetention);
                ds.sb3Return = Math.round((ds.sb3Return + marketShock + netReturnGain) * 100) / 100;
                ds.commissionRate = d.newCommission;
                ds.affiliates = Math.round((ds.affiliates - affiliateLoss) * 1000) / 1000;
                ds.aum = Math.round((ds.aum - aumLoss) * 10) / 10;
                ds.revenue = Math.round(ds.aum * ds.commissionRate * 10) / 10;
                ds.netIncome = Math.round(ds.revenue * 0.245 - d.marketingBudget);
                if (ds.sb3Return < 7.5) ds.ranking = Math.min(ds.ranking + 2, 10);
                else if (ds.sb3Return < 8.5) ds.ranking = Math.min(ds.ranking + 1, 10);
                else if (ds.sb3Return >= 9.4) ds.ranking = Math.max(ds.ranking - 1, 1);
                results.marketShock = marketShock;
                results.netReturnGain = Math.round(netReturnGain * 100) / 100;
                results.affiliateLoss = Math.round(affiliateLoss * 1000) / 1000;
                results.aumLoss = Math.round(aumLoss * 10) / 10;
                results.newReturn = ds.sb3Return;
                results.newRanking = ds.ranking;
                results.aum = ds.aum;
                results.revenue = ds.revenue;
                results.netIncome = ds.netIncome;
            }

            if (period === 4) {
                var newAccounts = 0;
                var digitalCost = 0;
                if (d.digitalStrategy === 1) {
                    newAccounts = 180000;
                    digitalCost = 180;
                } else if (d.digitalStrategy === 2) {
                    newAccounts = 120000;
                    digitalCost = 25;
                } else {
                    newAccounts = 0;
                    digitalCost = 0;
                }
                var investEffect = (d.capitalInvest / 100) * 0.6;
                var retainEffect = (d.capitalRetain / 100) * 0.4;
                var growEffect = (d.capitalGrow / 100) * newAccounts * 0.3;
                ds.sb3Return = Math.round((ds.sb3Return + investEffect) * 100) / 100;
                var retainedAffiliates = retainEffect * 0.15;
                ds.affiliates = Math.round((ds.affiliates + retainedAffiliates + newAccounts / 1000000) * 1000) / 1000;
                ds.aum = Math.round((ds.aum + retainedAffiliates * 6 + newAccounts * 0.000015) * 10) / 10;
                ds.netIncome = Math.round(ds.netIncome - digitalCost);
                ds.revenue = Math.round(ds.aum * ds.commissionRate * 10) / 10;
                ds.newAccountsProjected = Math.round(newAccounts * (d.capitalGrow / 100));
                if (ds.sb3Return >= 10.0) ds.ranking = Math.max(ds.ranking - 2, 1);
                else if (ds.sb3Return >= 9.4) ds.ranking = Math.max(ds.ranking - 1, 1);
                results.newAccounts = ds.newAccountsProjected;
                results.digitalCost = digitalCost;
                results.investEffect = Math.round(investEffect * 100) / 100;
                results.newReturn = ds.sb3Return;
                results.newRanking = ds.ranking;
                results.aum = ds.aum;
                results.revenue = ds.revenue;
                results.netIncome = ds.netIncome;
            }

            ds.returnHistory.push(ds.sb3Return);
            ds.aumHistory.push(ds.aum);
            ds.rankingHistory.push(ds.ranking);
            ds.revenueHistory.push(ds.revenue);

            // Platform score: the summary verdict band of the play so far mapped to 0-100 (needs improvement 0-49, adequate 50-69, good 70-84, excellent 85-100), placed inside the band by SB3 return.
            var vBand = this._verdict(ds.sb3Return, ds.ranking, ds.aum), vRet = ds.sb3Return, vScore;
            if (vBand === 'excellent') vScore = 85 + Math.min(15, (vRet - 10.0) * 10);
            else if (vBand === 'good') vScore = 70 + Math.min(14, (vRet - 9.4) / 0.6 * 14);
            else if (vBand === 'adequate') vScore = 50 + Math.min(19, (vRet - 8.5) / 0.9 * 19);
            else vScore = Math.min(49, Math.max(0, vRet) / 8.5 * 49);
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: Math.max(0, Math.min(100, Math.round(vScore))) });

            /* v1.1.0: racy setTimeout removed (read currentPeriod after the sync increment -> rendered N+2). Briefing/controls now refresh on the real 'period:submitted' event (wired in setupUI). */

            return results;
        }

