            uiManager.bind('varDisplay', 'domainState.varUsage',
                function(v) { return v.toFixed(0) + '%'; });
            uiManager.bind('revenueDisplay', 'domainState.revenue',
                function(v) { return Math.round(v).toLocaleString(); });

            // v1.1.0: refresh briefing + round controls on real period changes and on language switch
            if (!this._wired) {
                var _self = this;
                var _refresh = function() { try { _self._updateBriefing(window.mySimulation.state); } catch (e) {} };
