        // Verdict bands of the summary (same thresholds), shared with the platform score in calculateResults.
        // an emptied number field parses to NaN, which passes every range and sum check and would be written into the state
        _anyBlank(values) {
            for (var i = 0; i < values.length; i++) {
                if (typeof values[i] !== 'number' || isNaN(values[i])) return true;
            }
            return false;
        }

        _blankRefused() {
            window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_blank_field'), 'warning');
            return false;
        }

        _verdict(finalReturn, finalRanking, finalAum) {
            if (finalReturn >= 10.0 && finalRanking <= 4 && finalAum >= 410) return 'excellent';
            if (finalReturn >= 9.4 && finalRanking <= 6) return 'good';
            if (finalReturn >= 8.5) return 'adequate';
            return 'needs';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var finalReturn = last.results ? (last.results.newReturn || 0) : 0;
            var finalRanking = last.results ? (last.results.newRanking || 10) : 10;
            var finalAum = last.results ? (last.results.aum || 0) : 0;

            var t = function(k) { return window.mySimulation.t(k); };
            var performance = t('perf_' + this._verdict(finalReturn, finalRanking, finalAum));

            var insights = [];
            if (finalReturn >= 9.4) insights.push(t('insight_return_closed'));
            else insights.push(t('insight_return_below'));
            if (finalRanking <= 5) insights.push(t('insight_rank_strong'));
            else insights.push(t('insight_rank_low'));
            if (finalAum >= 400) insights.push(t('insight_aum_stable'));
            else if (finalAum >= 350) insights.push(t('insight_aum_pressure'));
            else insights.push(t('insight_aum_danger'));

            return {
                finalReturn: finalReturn,
                finalRanking: finalRanking,
                finalAum: finalAum,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            var period = state.currentPeriod;
            if (period === 1 && results.newVar > 90) return window.mySimulation.t('hint_high_var');
            if (period === 1 && results.returnBoost < 0.5) return window.mySimulation.t('hint_low_boost');
            if (period === 2 && results.fibraYield < 7.5) return window.mySimulation.t('hint_low_fibra_yield');
            if (period === 3 && results.newReturn < 7.0) return window.mySimulation.t('hint_crisis_deep');
            if (period === 3 && results.affiliateLoss > 0.2) return window.mySimulation.t('hint_high_portability');
            if (period === 4 && state.domainState.aum < 380) return window.mySimulation.t('hint_aum_danger');
            return null;
        }

