        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = window.mySimulation.t(round.descKey);
            }

            var allControls = ['round1Controls', 'round2Controls', 'round3Controls', 'round4Controls'];
            for (var i = 0; i < allControls.length; i++) {
                var el = document.getElementById(allControls[i]);
                if (el) el.style.display = (allControls[i] === round.controls) ? 'block' : 'none';
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new GestoraAdapter(), {
            simulationType: 'gestora_afore',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

